   187	/* ========================================================================= */
   188	/* 3. Static Inline Helper Functions (Strict Gatekeeper Compliant)           */
   189	/* ========================================================================= */
   190	
   191	/**
   192	 * @brief Check if a wire temperature value represents a fault or offline sentinel.
   193	 * @param deci_c Wire temperature in 0.1 deg C
   194	 * @return true if sentinel, false if valid measurement
   195	 */
   196	static inline bool telemetry_is_wire_sentinel(int16_t deci_c) {
   197	    const bool is_fault = (deci_c == MINIMC_TEMP_SENTINEL_FAULT);
   198	    const bool is_offline = (deci_c == MINIMC_TEMP_SENTINEL_OFFLINE);
   199	    return is_fault || is_offline;
   200	}
   201	
   202	/**
   203	 * @brief Convert wire deci_c (0.1 deg C) to normalized internal millicelsius (0.001 deg C).
   204	 * @param deci_c Input wire temperature
   205	 * @param out_millic Output normalized temperature in millicelsius
   206	 * @return Status code
   207	 */
   208	static inline telemetry_status_t telemetry_deci_to_millic(
   209	    int16_t deci_c,
   210	    int32_t *out_millic
   211	) {
   212	    if (out_millic == NULL) {
   213	        return TELEMETRY_ERR_NULL_PTR;
   214	    }
   215	
   216	    if (deci_c == MINIMC_TEMP_SENTINEL_FAULT) {
   217	        *out_millic = AISOC_TEMP_MILLIC_FAULT;
   218	        return TELEMETRY_OK;
   219	    }
   220	
   221	    if (deci_c == MINIMC_TEMP_SENTINEL_OFFLINE) {
   222	        *out_millic = AISOC_TEMP_MILLIC_OFFLINE;
   223	        return TELEMETRY_OK;
   224	    }
   225	
   226	    const bool below_min = (deci_c < MINIMC_TEMP_DECI_MIN);
   227	    const bool above_max = (deci_c > MINIMC_TEMP_DECI_MAX);
   228	    if (below_min || above_max) {
   229	        return TELEMETRY_ERR_RANGE_EXCEEDED;
   230	    }
   231	
   232	    const int32_t val = (int32_t)deci_c;
   233	    *out_millic = val * 100;
   234	    return TELEMETRY_OK;
   235	}
   236	
   237	/**
   238	 * @brief Convert internal millicelsius (0.001 deg C) to wire deci_c (0.1 deg C).
   239	 * @param millic Input internal temperature in millicelsius
   240	 * @param out_deci_c Output wire temperature
   241	 * @return Status code
   242	 */
   243	static inline telemetry_status_t telemetry_millic_to_deci(
   244	    int32_t millic,
   245	    int16_t *out_deci_c
   246	) {
   247	    if (out_deci_c == NULL) {
   248	        return TELEMETRY_ERR_NULL_PTR;
   249	    }
   250	
   251	    if (millic == AISOC_TEMP_MILLIC_FAULT) {
   252	        *out_deci_c = MINIMC_TEMP_SENTINEL_FAULT;
   253	        return TELEMETRY_OK;
   254	    }
   255	
   256	    if (millic == AISOC_TEMP_MILLIC_OFFLINE) {
   257	        *out_deci_c = MINIMC_TEMP_SENTINEL_OFFLINE;
   258	        return TELEMETRY_OK;
   259	    }
   260	
   261	    const bool below_min = (millic < AISOC_TEMP_MILLIC_MIN);
   262	    const bool above_max = (millic > AISOC_TEMP_MILLIC_MAX);
   263	    if (below_min || above_max) {
   264	        return TELEMETRY_ERR_RANGE_EXCEEDED;
   265	    }
   266	
   267	    const int32_t scaled = millic / 100;
   268	    *out_deci_c = (int16_t)scaled;
   269	    return TELEMETRY_OK;
   270	}
