   272	/**
   273	 * @brief Map wire status code to canonical sensor status enum.
   274	 * @param wire_status 8-bit wire status code
   275	 * @param out_status Output sensor status enum
   276	 * @return Status code
   277	 */
   278	static inline telemetry_status_t telemetry_map_sensor_status(
   279	    uint8_t wire_status,
   280	    aisoc_sensor_status_t *out_status
   281	) {
   282	    if (out_status == NULL) {
   283	        return TELEMETRY_ERR_NULL_PTR;
   284	    }
   285	
   286	    switch (wire_status) {
   287	        case MINIMC_WIRE_STATUS_OK:
   288	            *out_status = AISOC_SENSOR_OK;
   289	            break;
   290	        case MINIMC_WIRE_STATUS_OPEN:
   291	            *out_status = AISOC_SENSOR_OPEN;
   292	            break;
   293	        case MINIMC_WIRE_STATUS_SHORT:
   294	            *out_status = AISOC_SENSOR_SHORT;
   295	            break;
   296	        case MINIMC_WIRE_STATUS_TIMEOUT:
   297	            *out_status = AISOC_SENSOR_TIMEOUT;
   298	            break;
   299	        default:
   300	            *out_status = AISOC_SENSOR_UNKNOWN;
   301	            break;
   302	    }
   303	    return TELEMETRY_OK;
   304	}
