   306	/**
   307	 * @brief Evaluate data freshness quality based on elapsed monotonic milliseconds.
   308	 * @param elapsed_ms Elapsed time since last received sample
   309	 * @param sensor_status Physical status of the sensor
   310	 * @param out_quality Output quality rating
   311	 * @return Status code
   312	 */
   313	static inline telemetry_status_t telemetry_eval_data_quality(
   314	    uint32_t elapsed_ms,
   315	    aisoc_sensor_status_t sensor_status,
   316	    aisoc_data_quality_t *out_quality
   317	) {
   318	    if (out_quality == NULL) {
   319	        return TELEMETRY_ERR_NULL_PTR;
   320	    }
   321	
   322	    if (sensor_status != AISOC_SENSOR_OK) {
   323	        *out_quality = AISOC_QUALITY_FAULT;
   324	        return TELEMETRY_OK;
   325	    }
   326	
   327	    if (elapsed_ms < AISOC_FRESHNESS_STALE_MS) {
