   362	/**
   363	 * @brief Compute CRC-16/CCITT-FALSE over buffer (step-by-step, no compressed arithmetic).
   364	 * @param data Input byte buffer
   365	 * @param len Byte count
   366	 * @param out_crc Output calculated 16-bit CRC
   367	 * @return Status code
   368	 */
   369	static inline telemetry_status_t telemetry_calc_crc16(
   370	    const uint8_t *data,
   371	    size_t len,
   372	    uint16_t *out_crc
   373	) {
   374	    if (data == NULL || out_crc == NULL) {
   375	        return TELEMETRY_ERR_NULL_PTR;
   376	    }
   377	
   378	    uint16_t crc = 0xFFFFU;
   379	    for (size_t i = 0; i < len; ++i) {
   380	        const uint8_t byte_val = data[i];
   381	        crc ^= (uint16_t)((uint16_t)byte_val << 8);
   382	        for (uint8_t bit = 0; bit < 8; ++bit) {
   383	            const bool msb_set = ((crc & 0x8000U) != 0U);
   384	            if (msb_set) {
   385	                crc = (uint16_t)((crc << 1) ^ 0x1021U);
   386	            } else {
   387	                crc = (uint16_t)(crc << 1);
   388	            }
   389	        }
   390	    }
